import { cacheTag } from 'next/cache'

export type Post = {
  id: string
  title: string
  content: string
  createdAt: number
}

// Stand-in for a database. Module scope keeps it alive across requests in dev.
const posts: Post[] = [
  {
    id: '1',
    title: 'Hello world',
    content: 'The first post.',
    createdAt: 0,
  },
]

/**
 * Cached posts list. Tagged `posts` so a Server Action can invalidate it.
 */
export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')

  return posts.map((post) => ({ ...post }))
}

export async function insertPost(input: {
  title: string
  content: string
}): Promise<Post> {
  const post: Post = {
