import { updateTag } from 'next/cache'
import { insertPost } from './posts'

export type CreatePostResult = { error: string } | { error: null }

export async function createPost(
  _prevState: CreatePostResult | null,
  formData: FormData
): Promise<CreatePostResult> {
  const title = String(formData.get('title') ?? '').trim()
  const content = String(formData.get('content') ?? '').trim()

  if (!title) {
    return { error: 'Title is required.' }
  }

  await insertPost({ title, content })

  // `updateTag` expires the `posts` cache and refreshes it as part of this
  // action, so the response the user gets back already contains the new post.
  // `revalidateTag` would only mark the entry stale and could serve the old
  // cached list once more while revalidating in the background.
  updateTag('posts')

  return { error: null }
}

